list_inventory_locations.code:
final response = await client.inventoryLocations
    .listInventoryLocations(queryParams: {'q': 'Sydney'});
final locations = (response.map as Map)['inventory_locations'] as List;
for (final location in locations) {
  print('${(location as Map)['id']} ${location['name']}');
}

create_inventory_location.code:
final response = await client.inventoryLocations.createInventoryLocation({
  'name': 'Perth Warehouse',
  'address': '4 Example Street, Perth WA 6000',
});
final location = (response.map as Map)['inventory_location'] as Map;
print(location['id']);

get_inventory_location.code:
final response = await client.inventoryLocations.getInventoryLocation(4);
final location = (response.map as Map)['inventory_location'] as Map;
print('${location['name']} ${location['address']}');

update_inventory_location.code:
final response = await client.inventoryLocations.updateInventoryLocation(19, {
  'name': 'Perth Warehouse',
  'address': '10 Example Street, Perth WA 6000',
  'active': true,
  'default': false,
});
final location = (response.map as Map)['inventory_location'] as Map;
print('${location['address']} ${location['active']}');

get_inventory_location_stock.code:
final response = await client.inventoryLocations.getInventoryLocationStock(4);
final items = (response.map as Map)['items'] as List;
for (final item in items) {
  final product = (item as Map)['product'] as Map;
  print('${product['sku']} ${item['available_stock']}');
}

